command:
pnpm --filter @iris/runtime exec tsx -e 'import assert from "node:assert/strict";
import {execFileSync,spawnSync} from "node:child_process";
import {existsSync,lstatSync,readFileSync,realpathSync,symlinkSync,writeFileSync,mkdtempSync} from "node:fs";
import os from "node:os";
import path from "node:path";
import {canonicalNodeRuntime,node24Path} from "./src/node-runtime.ts";
import {runDeclaredProjectScript} from "./src/project-test.ts";
(async()=>{
  assert.equal(process.platform,"darwin");
  assert(!existsSync("/Users/RARW") && !existsSync("/Users/bill"));
  const node=canonicalNodeRuntime();
  const actionBin=realpathSync(execFileSync("/usr/bin/which",["pnpm"],{encoding:"utf8"}).trim());
  assert.equal(execFileSync(actionBin,["--version"],{encoding:"utf8"}).trim(),"10.15.0");
  const cli=actionBin.endsWith("/pnpm/bin/pnpm.cjs")?actionBin:realpathSync(path.resolve(path.dirname(actionBin),"..","pnpm","bin","pnpm.cjs"));
  const pkg=JSON.parse(readFileSync(path.resolve(path.dirname(cli),"..","package.json"),"utf8"));
  assert.equal(pkg.name,"pnpm");assert.equal(pkg.version,"10.15.0");
  assert.equal(execFileSync(node.path,[cli,"--version"],{encoding:"utf8"}).trim(),"10.15.0");
  const requested=path.join(path.dirname(node.path),"pnpm");
  const before=spawnSync("pnpm",["--version"],{env:{...process.env,PATH:node24Path()},encoding:"utf8"});
  const probe=mkdtempSync(path.join(os.tmpdir(),"m66-pnpm-probe-"));
  writeFileSync(path.join(probe,"package.json"),JSON.stringify({packageManager:"pnpm@10.15.0",scripts:{probe:"node probe.mjs"}}));
  writeFileSync(path.join(probe,"probe.mjs"),"console.log('\''M66_PINNED_PNPM_PROBE'\'')\n");
  const legacyBefore=await runDeclaredProjectScript(probe,"probe");
  try { lstatSync(requested);assert.equal(realpathSync(requested),cli,"Refuse to replace an existing different executable"); }
  catch(error) { if(error.code!=="ENOENT")throw error;symlinkSync(cli,requested); }
  assert.equal(realpathSync(requested),cli);
  const version=execFileSync(requested,["--version"],{env:{...process.env,PATH:node24Path()},encoding:"utf8"}).trim();
  assert.equal(version,"10.15.0");
  const legacyAfter=await runDeclaredProjectScript(probe,"probe");
  assert.equal(legacyAfter.passed,true);assert.match(legacyAfter.stdout,/M66_PINNED_PNPM_PROBE/);
  const report={status:"PASS",node,actionBin,pinnedCli:cli,requested,resolved:realpathSync(requested),version,canonicalPathBefore:{status:before.status,errorCode:before.error?.code??null,stdout:before.stdout??""},legacyBefore,legacyAfter};
  writeFileSync(path.join(os.tmpdir(),"m66-pnpm-provision.json"),JSON.stringify(report,null,2)+"\n",{mode:0o600});
  console.log(JSON.stringify(report,null,2));
})().catch(error=>{console.error(error);process.exitCode=1;});
'
